def InvocationRequiresActiveFunction():
    for iid in inv_status:
        if inv_status[iid] == "IN_PROGRESS":
            fid = inv_func[iid]
            if fid in func_status:
                if func_status[fid] != "ACTIVE":
                    return False
    return True


# check: every indexed document belongs to an existing index

def DocumentRequiresExistingIndex():
    for docid in doc_status:
        if doc_status[docid] == "INDEXED":
            xid = doc_index[docid]
            if xid in index_status:
                if index_status[xid] != "EXISTS":
                    return False
    return True


# check: every existing index belongs to an ACTIVE domain

def IndexRequiresActiveDomain():
    for xid in index_status:
        if index_status[xid] == "EXISTS":
            did = index_domain[xid]
            if did in domain_status:
                if domain_status[did] != "ACTIVE":
                    return False
    return True
